import{_ as a,o as s,c as r,ag as t}from"./chunks/framework.CrXGS008.js";const u=JSON.parse('{"title":"Car Wash","description":"","frontmatter":{},"headers":[],"relativePath":"car-wash/index.md","filePath":"car-wash/index.md"}'),n={name:"car-wash/index.md"};function o(i,e,l,h,c,d){return s(),r("div",null,[...e[0]||(e[0]=[t(`<h1 id="car-wash" tabindex="-1">Car Wash <a class="header-anchor" href="#car-wash" aria-label="Permalink to &quot;Car Wash&quot;">​</a></h1><p>Drive in, pick a program, and the vehicle rolls through spinning brushes, foam, rinse arches and a steam dryer while everyone around sees the same wash. On foot, players grab a pressure washer and clean the dirt off level by level. Every location is placed in game and every setting is edited in game.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li><strong>Drive-through tunnels</strong>: brushes sized to the vehicle width, soap and rinse arches, steam dryer, synced for every player nearby. See <a href="/car-wash/tunnels">Tunnels</a>.</li><li><strong>Wash programs</strong>: name, price, speed, and which steps run (soap, rinse, dry, wax). Wax keeps the vehicle clean for as long as you choose.</li><li><strong>Pressure washers</strong> on any world prop you list, or on stations you place, paid per dirt level. See <a href="/car-wash/pressure-washers">Pressure washers</a>.</li><li><strong>In-game tunnel editor</strong>: create a tunnel where you stand or copy a base game car wash, move each part with the keyboard, save.</li><li><strong>Everything in <code>/nay</code></strong>: prices, programs, job discounts, payment account, blocked vehicle classes, blips with a visual icon and colour picker. See <a href="/car-wash/settings">Settings</a>.</li><li><strong>Fair and safe</strong>: one vehicle per tunnel, wrong-way and blocked-lane checks, payments and tunnel reservation validated on the server.</li><li><strong>Job discounts</strong> and a price percentage per tunnel. Players pay from cash, bank, or cash then bank.</li><li><strong>Map aware</strong>: the static brushes of the map are hidden along each tunnel and come back when the resource stops. At Strawberry, the brushless map files replace the default car wash.</li><li><strong>HTTP API and webhooks</strong>: wash history and statistics for your website or bot, a Discord message for every wash. See <a href="/car-wash/api">API and webhooks</a>.</li><li><strong>Six languages</strong>: English, French, Spanish, Portuguese, Polish, German.</li></ul><h2 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;Compatibility&quot;">​</a></h2><ul><li>Frameworks: ESX Legacy, QBCore, QBox, ox_core, detected automatically.</li><li>Target (optional, for pressure washers): ox_target or qb-target. Without one, players use a key prompt.</li><li>Dependencies: oxmysql and <code>nay_lib</code> (included with your purchase).</li></ul><h2 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>State</th><th>Client (resmon)</th></tr></thead><tbody><tr><td>Idle</td><td>0.00 ms</td></tr><tr><td>Washing a vehicle</td><td>about 0.08 ms</td></tr></tbody></table><p>Measured with resmon on game build 3751.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ensure oxmysql</span></span>
<span class="line"><span>ensure nay_lib</span></span>
<span class="line"><span>ensure nay_car_wash</span></span></code></pre></div><p>Full steps on the <a href="/getting-started">Getting started</a> page. Then give yourself <code>nay_car_wash.config</code> (or <code>nay.admin</code>) and open <code>/nay</code>. Two tunnels are ready out of the box: Strawberry and Little Seoul.</p>`,12)])])}const g=a(n,[["render",o]]);export{u as __pageData,g as default};
